/// @file tests/cpu/vib/test_frequencies_vs_pyscf.cpp
/// @brief Frequency parity test: cpu::vib::Hessian numerical-Hessian
///        frequencies vs PySCF analytic-Hessian harmonic_analysis
///        (spec phase4-vibrations-02, ac-005).
///
/// The reference data (optimized geometry + analytic-Hessian
/// frequencies) is checked in as pyscf_frequencies_data.h, generated by
/// tests/cpu/vib/reference/generate_pyscf_frequencies.py from a genuine
/// PySCF 2.x run (provenance in pyscf_frequencies.json). The numerical
/// Hessian here and PySCF's analytic Hessian are evaluated at the SAME
/// optimized geometry, so the only gap is finite-difference truncation.

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <vector>

#include "atomiverse/core/mat3.h"
#include "atomiverse/cpu/frame.h"
#include "atomiverse/cpu/scf/integrals.h"
#include "atomiverse/cpu/scf/scf_evaluator.h"
#include "atomiverse/cpu/scf/scf_solve.h"
#include "atomiverse/cpu/vib/hessian.h"
#include "atomiverse/cpu/vib/hessian_result.h"
#include "atomiverse/facade/stage.h"

#include "cpu/vib/reference/pyscf_frequencies_data.h"

using namespace ATV;

namespace {

/// @brief Build a cpu::Frame from a checked-in reference molecule.
/// @param ref Reference molecule (optimized geometry, atomic numbers).
/// @return Frame with positions in Angstrom and atomic numbers in type.
cpu::Frame make_frame(const pyscf_ref::RefMolecule& ref) {
    const int n = ref.natoms;
    cpu::Frame f(n);
    for (int i = 0; i < n; ++i) {
        f.atoms.x(i)    = ref.geom[i].x;
        f.atoms.y(i)    = ref.geom[i].y;
        f.atoms.z(i)    = ref.geom[i].z;
        f.atoms.type(i) = ref.geom[i].Z;
    }
    f.box = Mat3::cubic(100.0);
    return f;
}

/// @brief Tight RHF config so each displaced SCF is gradient-stationary.
/// @param ints Integral pack supplying the electron count.
/// @return RHF SCFConfig with `tol = 1e-12`, `conv_tol_grad = 1e-9`.
cpu::scf::SCFConfig tight_rhf_config(const cpu::scf::IntegralPack& ints) {
    auto cfg = cpu::scf::rhf_config(ints, /*tol=*/1e-12);
    cfg.conv_tol_grad = 1e-9;
    return cfg;
}

/// @brief Run the cpu::vib::Hessian driver and return sorted frequencies.
/// @param frame Equilibrium geometry (RHF / 6-31G).
/// @return HessianResult with frequencies/normal modes populated.
cpu::vib::HessianResult run_vib(cpu::Frame frame) {
    auto ints = cpu::scf::build_integrals(frame,
                                          cpu::scf::BasisSet::Pople631G);
    auto cfg  = tight_rhf_config(ints);

    cpu::vib::Hessian driver;
    driver.on(ATV::vib::Phase::force)
          .add(cpu::scf::SCFEvaluator{cfg, cpu::scf::BasisSet::Pople631G});
    driver.build();
    return driver.run(frame);
}

/// @brief Max absolute deviation between two sorted frequency lists.
/// @param a First frequency list [cm^-1].
/// @param b Second frequency list [cm^-1].
/// @return Maximum |a_i - b_i| over matched, sorted modes.
double max_deviation(std::vector<double> a, std::vector<double> b) {
    std::sort(a.begin(), a.end());
    std::sort(b.begin(), b.end());
    EXPECT_EQ(a.size(), b.size());
    double m = 0.0;
    const size_t n = std::min(a.size(), b.size());
    for (size_t i = 0; i < n; ++i)
        m = std::max(m, std::abs(a[i] - b[i]));
    return m;
}

/// @brief Look up a reference molecule by name.
const pyscf_ref::RefMolecule& ref(const char* name) {
    for (const auto& m : pyscf_ref::reference())
        if (std::string(m.name) == name) return m;
    throw std::runtime_error(std::string("no reference for ") + name);
}

/// @brief Run the parity check for one molecule against the references.
/// @param name      Reference molecule name.
/// @param tol_cm1   Acceptance tolerance in cm^-1.
void check_molecule(const char* name, double tol_cm1) {
    const auto& r = ref(name);
    auto result = run_vib(make_frame(r));

    // ac-003: exactly 3N-6 (nonlinear) projected modes for these molecules.
    EXPECT_FALSE(result.is_linear) << name << " must be nonlinear";
    ASSERT_EQ(static_cast<int>(result.frequencies.size()),
              3 * r.natoms - 6)
        << name << " must yield exactly 3N-6 modes";
    EXPECT_EQ(result.frequencies.size(), r.freq.size());

    std::vector<double> got(result.frequencies.begin(),
                            result.frequencies.end());
    const double dev = max_deviation(got, r.freq);
    EXPECT_LE(dev, tol_cm1)
        << name << ": max frequency deviation vs PySCF analytic Hessian = "
        << dev << " cm^-1 (tolerance " << tol_cm1 << ")";
    // Always report the achieved deviation for the record.
    std::cout << "[ parity ] " << name << " max deviation = " << dev
              << " cm^-1\n";
}

} // namespace

// ── ac-005: H2O / NH3 / CH4 numerical frequencies vs PySCF ──────────────

TEST(VibFrequenciesVsPyscf, Water) {
    check_molecule("h2o", 5.0);
}

TEST(VibFrequenciesVsPyscf, Ammonia) {
    check_molecule("nh3", 5.0);
}

TEST(VibFrequenciesVsPyscf, Methane) {
    check_molecule("ch4", 5.0);
}

// ── Provenance: reference data is from a genuine PySCF run ───────────────

TEST(VibFrequenciesVsPyscf, ReferenceProvenance) {
    EXPECT_STRNE(pyscf_ref::kPyscfVersion, "");
    EXPECT_EQ(pyscf_ref::reference().size(), 3u);
}
